"""Operator storage encoding only; frozen scientific producers/verifiers stay intact."""
import sys,json,os,hashlib,tarfile,tempfile,gzip,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'scripts/platform/rtx_trajectory_cost_v3'))
from prepare import STUDY,save,sha,now
import package,guards
original_publish=package.publish
original_tar_open=tarfile.open
original_os_link=os.link

def namespace(p):
    p=Path(p)
    if os.name=='nt' and not str(p).startswith('\\\\?\\'):
        return Path('\\\\?\\'+str(p.absolute()))
    return p

def canonical(p):
    return Path(str(Path(p).resolve()).removeprefix('\\\\?\\'))

def io_link(src,dst,**kwargs):
    return original_os_link(namespace(src),namespace(dst),**kwargs)

def transport_tar_open(name=None,mode='r',fileobj=None,**kwargs):
    if fileobj is None and name is not None and mode=='r' and Path(name).name=='complete.tar.gz':
        packed=namespace(name);plain=packed.with_name('complete.transport.tar')
        with gzip.open(packed,'rb') as inp,plain.open('wb') as out:shutil.copyfileobj(inp,out,1024*1024)
        return original_tar_open(plain,mode='r:',**kwargs)
    return original_tar_open(name=name,mode=mode,fileobj=fileobj,**kwargs)

def hardlink_equal_bytes(stage,mode,arm,anonymous=False):
    stage=namespace(Path(stage).resolve());workspace=(ROOT/'work').resolve()
    assert canonical(stage).is_relative_to(workspace) and stage.name.startswith(('package-stage-','anonymous-stage-'))
    seen={};linked=[];saved=0
    for p in sorted(stage.rglob('*')):
        if not p.is_file() or p.is_symlink():continue
        size=p.stat().st_size
        if not size:continue
        digest=sha(p);key=(size,digest)
        if key not in seen:seen[key]=p;continue
        prior=seen[key]
        assert canonical(p).is_relative_to(canonical(stage)) and canonical(prior).is_relative_to(canonical(stage))
        assert p.stat().st_size==prior.stat().st_size and sha(prior)==digest
        temp=p.with_name(p.name+'.storage-link-tmp')
        assert not temp.exists()
        os.link(prior,temp)
        os.replace(temp,p)
        assert sha(p)==digest
        linked.append({'member':p.relative_to(stage).as_posix(),'same_bytes_as':prior.relative_to(stage).as_posix(),'sha256':digest,'bytes':size})
        saved+=size
    result={'schema':'RTX_V3.lossless_tar_hardlink_storage','utc':now(),'mode':mode,'arm':arm,'anonymous':anonymous,'operator_source_sha256':sha(Path(__file__)),'logical_member_bytes_changed':0,'shared_byte_members':len(linked),'duplicate_payload_bytes_avoided':saved,'links':linked,'scope':'Only derived archive staging files are linked to equal bytes in the same stage. Original raw evidence, frozen numerical source, runtime, timers, parameters and model execution are untouched. Python tarfile stores ordinary internal hardlink entries; extraction materializes every logical member, independently hash-checked and recomputed by the unchanged offline verifier.'}
    save(stage/'STORAGE_ENCODING.json',result)
    save(ROOT/'work'/('STORAGE_'+mode+'_'+arm+('_ANON' if anonymous else '')+'.json'),result)
    return result

def storage_publish(stage,mode,arm,anonymous=False):
    r=hardlink_equal_bytes(stage,mode,arm,anonymous)
    print('Lossless archive storage',mode,arm,anonymous,'duplicate bytes avoided',r['duplicate_payload_bytes_avoided'],flush=True)
    return original_publish(stage,mode,arm,anonymous)

def self_check():
    base=ROOT/'work/package-stage-storage-selfcheck';base.mkdir(exist_ok=False)
    (base/'a').write_bytes(b'abc'*4096);(base/'nested').mkdir();(base/'nested/b').write_bytes(b'abc'*4096)
    r=hardlink_equal_bytes(base,'STORAGE_SELF_CHECK','NONE')
    archive=base.parent/'storage-selfcheck.tar'
    with tarfile.open(archive,'w') as tar:
        for p in sorted(base.rglob('*')):
            if p.is_file():
                info=tar.gettarinfo(str(p),arcname=p.relative_to(base).as_posix())
                with p.open('rb') as f:tar.addfile(info,f)
    restored=ROOT/'work/storage-selfcheck-restored';restored.mkdir(exist_ok=False)
    with tarfile.open(archive) as tar:
        assert any(x.islnk() for x in tar.getmembers())
        tar.extractall(restored,filter='data')
    for p in base.rglob('*'):
        if p.is_file():assert sha(p)==sha(restored/p.relative_to(base))
    print('PASS: actual NTFS hardlinks, standard tar hardlink encoding, safe fresh extraction, every logical member byte identical',flush=True)

def main():
    mode=sys.argv[1]
    if mode=='self-check':return self_check()
    guards.check_manifest('F0_MANIFEST.json')
    package.publish=storage_publish
    description=STUDY/'ARTIFACT_STORAGE_ENCODING.json'
    save(description,{'schema':'RTX_V3.archive_storage_operator','operator_source_sha256':sha(Path(__file__)),'operator_source_utf8':Path(__file__).read_text(encoding='utf-8'),'reason':'Frozen packaging copies complete F0/F1/F2/B-start retrieval snapshots. Equal archive part bytes occur at multiple retained logical paths. Store these equal immutable payloads through standard tar internal hardlinks to avoid duplicating gigabytes while preserving every member and proof. Windows extended path namespace is used only for archive I/O to avoid MAX_PATH failures on deeply nested snapshot members.','numerical_source_changed':False,'observer_and_timer_changed':False,'logical_member_bytes_changed':False,'original_evidence_mutated':False,'acceptance':'Every capsule still undergoes actual fresh extraction, exact member hashes and full independent offline recomputation using the unchanged frozen verifier.'})
    # Only filesystem spellings change: all resolve to the same repository/stage.
    package.ROOT=namespace(ROOT);package.STUDY=namespace(STUDY)
    package.ART={k:namespace(v) for k,v in package.ART.items()}
    os.link=io_link
    tarfile.open=transport_tar_open
    if mode=='seal-predictions':
        import study
        study.seal_predictions()
    elif mode in ['complete-archives','resume-complete-archives']:
        import closeout
        if mode=='complete-archives':closeout.reached()
        if mode=='resume-complete-archives':
            candidates=[p for p in (ROOT/'artifacts/rtx_trajectory_sufficiency_v3').glob('complete-*.parts.json') if not p.name.startswith('complete-anonymous-')]
            assert len(candidates)==1
            index=candidates[0];a=json.loads(index.read_text(encoding='utf-8'))
            if not (STUDY/'A_COMPLETE_ARCHIVE.json').exists():
                fresh=namespace(ROOT/'work'/('clean-A-'+a['sha256'][:16]+'-transport4'))
                result=package.reconstruct(namespace(index),fresh)
                save(STUDY/'A_COMPLETE_ARCHIVE.json',{'path':index.relative_to(ROOT).as_posix(),**a,'offline_reconstruction':result,'actual_created_utc':now(),'archive_bytes_unchanged_after_transport_retry':True})
            if not (STUDY/'A_COMPLETE_ANONYMOUS_ARCHIVE.json').exists():
                anonymous_indexes=list((ROOT/'artifacts/rtx_trajectory_sufficiency_v3').glob('complete-anonymous-*.parts.json'))
                if anonymous_indexes:
                    assert len(anonymous_indexes)==1
                    index=anonymous_indexes[0];a=json.loads(index.read_text(encoding='utf-8'))
                    result=package.reconstruct(namespace(index),namespace(ROOT/'work'/('clean-A-'+a['sha256'][:16]+'-transport4')))
                    save(STUDY/'A_COMPLETE_ANONYMOUS_ARCHIVE.json',{'path':index.relative_to(ROOT).as_posix(),**a,'offline_reconstruction':result,'actual_created_utc':now(),'archive_bytes_unchanged_after_transport_retry':True})
                else:
                    import anonymous
                    anonymous.make(namespace(ROOT/'work/package-stage-A-complete'),'complete','A')
        else:package.make('complete','A')
        package.make('complete','B')
        rows=[]
        for p in sorted(STUDY.glob('*_ARCHIVE.json')):
            a=json.loads(p.read_text(encoding='utf-8'));rows.append({'arm':a['arm'],'mode':a['mode'],'anonymous':a['anonymous'],'index':a['path'],'index_sha256':sha(ROOT/a['path']),'archive_sha256':a['sha256'],'bytes':a['bytes'],'parts':a['parts'],'actual_offline_result':a['offline_reconstruction']})
        save(STUDY/'COMPLETE_ARTIFACT_MANIFEST.json',{'schema':'RTX_V3.joint_artifact_index','created_utc':now(),'archives':rows,'formal_observations_shared':False,'shared_engineering':'same run IDs disclosed, not extra independent A/B samples','external_binary_assets_omitted':True,'initial_F0_ARTIFACT_MANIFEST_preserved':True,'reason_for_new_name':'The initial ARTIFACT_MANIFEST.json is bound by F0. Preserve its exact bytes and publish the final derived archive index separately.'})
    else:raise ValueError(mode)

if __name__=='__main__':main()
